async function runOnboardingSteps(steps, onError = async () => undefined, signal?: AbortSignal) {
    for (const step of steps) {
        if (signal?.aborted) return;
        try {
            await step.run();
        }
        catch (error) {
            if (signal?.aborted) return;
            try {
                await onError(step.name, error);
            }
            catch {
                // Background onboarding must continue even if error reporting fails.
            }
        }
    }
}
function createSingleFlightRunner() {
    let inFlight;
    return (operation) => {
        if (inFlight)
            return inFlight;
        const current = Promise.resolve().then(operation).finally(() => {
            if (inFlight === current)
                inFlight = undefined;
        });
        inFlight = current;
        return current;
    };
}
function setupGuideNextStep(options) {
    const item = options || {};
    if (item.simpleSftpReady === false) {
        return {
            message: `配置说明已打开。下一步：先安装或升级配套 SimpleSFTP。${String(item.simpleSftpMessage || "")}`,
            action: "打开扩展管理",
        };
    }
    if (!item.setupComplete) {
        return {
            message: "配置说明已打开。下一步：在“设置 > 服务器”手动填写 Hub/Worker 会话和项目父目录。",
            action: "打开服务器设置",
        };
    }
    if (Number(item.workerCount || 0) < 1) {
        return {
            message: "配置说明已打开。Hub 已配置；下一步：添加至少一个执行 Worker。",
            action: "添加 Worker",
        };
    }
    if (!item.workspaceOpen) {
        return {
            message: "配置说明已打开。服务器已配置；下一步：打开要运行实验的本地项目文件夹。",
            action: "选择项目并继续",
        };
    }
    return {
        message: "配置说明已打开。服务器和本地项目已就绪；下一步：识别工作区。",
        action: "识别工作区",
    };
}
const SETUP_GUIDE_MAX_STEPS = 4;
const planSubmitProgress = {
    isLocal(record) {
        if (!record || typeof record !== "object")
            return false;
        if (record.localSubmissionProgress === true)
            return true;
        const operationId = String(record.operationId || record.opId || record.id || "");
        const payload = record.payload && typeof record.payload === "object" ? record.payload : {};
        const latestEvent = record.latestEvent && typeof record.latestEvent === "object" ? record.latestEvent : {};
        const latestPayload = latestEvent.payload && typeof latestEvent.payload === "object" ? latestEvent.payload : {};
        const accepted = [record, payload, latestPayload].some((row) => row.submissionAccepted === true || row.schedulerStarted === true);
        return operationId.startsWith("plan-submit-") && !accepted;
    },
};
