    async ensureWorkerCodeSyncProof(target, root, fingerprint, manifest, includePaths, scopePaths, inventoryScopePaths, warmProofKey, progressReport?) {
        const probe = this.lastWorkerProbes?.[target.id] || {};
        if (probe.capabilities?.actionEndpoints?.["register-code-sync-proof"] !== true) return undefined;
        const cached = this.codeSyncAgentProofs.get(warmProofKey);
        if (cached && cached.manifestDigest === fingerprint) return cached;
        const projectId = DistributedPlanQueue.canonicalProjectId(root);
        const scopeSignature = sha256Text(JSON.stringify({ includePaths: [...(includePaths || [])].map(String).sort(),
            scopePaths: [...(scopePaths || [])].map(String).sort(), inventoryScopePaths: [...(inventoryScopePaths || [])].map(String).sort() }));
        const client = this.client;
        const asynchronous = probe.capabilities?.endpoints?.codeSyncProofAsync === true;
        const operationId = makeOpId("code-sync-proof");
        const request = {
            schemaVersion: 1, opId: operationId, projectId, workerId: target.id,
            codeFingerprint: fingerprint, manifestDigest: fingerprint, scopeSignature, codeManifest: manifest,
            ...(asynchronous ? { async: true } : {}),
        };
        const result: any = asynchronous ? await waitForCodeSyncProof({
            operationId, workerId: target.id, manifestDigest: fingerprint, scopeSignature,
            submit: () => client.postWorkerAction(target.id, "register-code-sync-proof", request),
            query: () => client.getWorkerOperation(target.id, operationId), progress: progressReport,
            assertCurrent: () => { if (workspaceRoot() !== root || this.client !== client) throw new UiCommandCancelled("项目或连接已切换，同步登记查询已停止。"); },
        }) : await client.postWorkerAction(target.id, "register-code-sync-proof", request);
        if (workspaceRoot() !== root || this.client !== client) throw new UiCommandCancelled("工作区或连接已切换，Worker 代码 proof 注册已取消。");
        const proofId = String(result?.proofId || "").trim();
        const runtimeGeneration = String(result?.runtimeGeneration || "").trim();
        const fileCount = Number(result?.fileCount);
        if (result?.ok !== true || String(result?.manifestDigest || "") !== fingerprint
            || String(result?.scopeSignature || "") !== scopeSignature || !/^[a-f0-9]{64}$/.test(proofId)
            || !runtimeGeneration || fileCount !== Object.keys(manifest).length)
            throw new Error(`Worker ${target.id} 未确认完整代码同步 proof：${String(result?.error || "回执身份不匹配")}`);
        const proof = { proofId, manifestDigest: fingerprint, scopeSignature, fileCount,
            runtimeGeneration, verifiedAt: String(result?.verifiedAt || "") };
        this.codeSyncAgentProofs.set(warmProofKey, proof);
        while (this.codeSyncAgentProofs.size > 128) this.codeSyncAgentProofs.delete(this.codeSyncAgentProofs.keys().next().value);
        return proof;
    }
    rememberCodeSyncWarmProof(key) {
        if (!this.codeSyncWarmProofs) return;
        this.codeSyncWarmProofs.set(key, Date.now() + 5 * 60_000);
        while (this.codeSyncWarmProofs.size > 128) this.codeSyncWarmProofs.delete(this.codeSyncWarmProofs.keys().next().value);
    }
    async inspectCodeSyncTarget(target, paths) {
        const base = this.resolveAgentBase(target);
        const token = String(this.tunnelConfig?.token || "");
        const batches = [];
        for (let index = 0; index < paths.length; index += 30) batches.push(paths.slice(index, index + 30));
        const chunks = await mapLimited(batches, 3, async (batch) => {
            const query = new URLSearchParams();
            for (const file of batch) query.append("path", file);
            const controller = new AbortController();
            const timer = setTimeout(() => controller.abort(), 20000);
            try {
                const response = await fetch(`${base}/api/code-sync/inspect?${query.toString()}`, { headers: token ? { "X-Simple-Agent-Token": token } : undefined, signal: controller.signal });
                if (!response.ok) throw new Error(`HTTP ${response.status}`);
                const data: any = JSON.parse((await readBoundedWebResponse(response, 4 * 1024 * 1024, "Worker code sync proof")).toString("utf8"));
                if (data?.ok !== true || !Array.isArray(data.files) || data.files.length !== batch.length)
                    throw new Error(String(data?.error || "响应不完整"));
                const rows = [];
                for (let i = 0; i < batch.length; i++) {
                    if (data.files[i]?.path !== batch[i]) throw new Error("文件顺序不一致");
                    rows.push({ ...data.files[i], gitAvailable: data.gitAvailable === true });
                }
                return rows;
            }
            catch (error) {
                throw new Error(`${target.label} 上传结果校验失败（${errorMessage(error)}）；请先确认 Agent 已更新且隧道可用。`);
            }
            finally { clearTimeout(timer); }
        });
        return chunks.flat();
    }
