    async apiDraftCleanup(params = {}) {
        await this.refreshDraftPlans(true);
        const root = workspaceRoot();
        if (!root)
            throw new Error("需要先打开工作区。");
        const requested = stringArrayField(params, "paths");
        if (!requested.length)
            throw new Error("清理必须提供精确文件路径列表。");
        const targets = await this.draftCleanupConfirmationTargets(root, requested);
        const canonical = targets.map((item) => item.path).sort();
        const confirmed = stringArrayField(params, "confirmedPaths").map((value) => path.resolve(root, value)).sort();
        if (params.confirm !== true || params.pathConfirmed !== true || JSON.stringify(confirmed) !== JSON.stringify(canonical)) {
            throw confirmationRequired({ operation: "drafts.cleanup", requires: ["confirm", "pathConfirmed", "confirmedPaths"], targets,
                paths: requested, confirm: undefined, pathConfirmed: undefined, confirmedPaths: undefined });
        }
        const result = await this.withHostOperationLease("cleanupDrafts", "将草稿移入 clean_dir", () =>
            DraftPlans_1.cleanupApprovedDrafts(root, this.draftPlanState.drafts || [], requested), {
                resources: [{ server: "local", project: root, target: path.join(root, "clean_dir") }],
            });
        await this.refreshDraftPlans(true);
        return { ok: true, moved: result.moved, destinationRoot: path.join(root, "clean_dir") };
    }
    async draftCleanupConfirmationTargets(root, requested) {
        const candidates = await DraftPlans_1.listCleanupCandidates(root, this.draftPlanState.drafts || []);
        const normalizedRequested = requested.map((value) => String(value || "").replace(/\\/g, "/").replace(/^\.\//, ""));
        const requestedSet = new Set(normalizedRequested);
        if (requestedSet.size !== normalizedRequested.length)
            throw new Error("草稿清理路径包含重复项。");
        const selected = candidates.filter((item) => requestedSet.has(item.path));
        if (!selected.length || selected.length !== requestedSet.size)
            throw new Error("草稿清理路径已变化；请重新获取候选列表后再确认。");
        return selected.map((item) => ({
            label: `${item.path} · ${item.reason}`,
            path: path.resolve(root, item.path),
            destination: path.resolve(root, "clean_dir", ...item.path.split("/")),
        }));
    }

    async syncDraftFilesForRun(body, record) {
        await this.prepareSftpTargets("runDraftDebug", "simpleSftpMac.uploadFiles");
        const topology = this.assertPlanTopologyReady("草稿 Debug 运行");
        const selectedWorkerId = this.planSchedulerWorkerId(body);
        const targets = topology.mode === "worker_pool" && selectedWorkerId
                ? this.workerCodeSyncTargets().filter((target) => target.id === selectedWorkerId)
                : this.workerCodeSyncTargets();
        const enabledTargets = targets.filter(Boolean);
        if (!enabledTargets.length)
            throw new Error("没有可用于草稿同步的 Worker 目标。");
        const root = workspaceRoot();
        if (!root)
            throw new Error("需要先打开工作区。");
        const relativeFiles = uniqueStrings([record.draftPlanPath, ...(record.draftConfigPaths || [])]);
        const files = [];
        for (const relative of relativeFiles) {
            const full = safeDraftWorkspaceChild(root, relative);
            const stat = await fs.stat(full);
            if (!stat.isFile())
                throw new Error(`草稿同步文件不是普通文件：${relative}`);
            files.push({ localPath: full, remoteName: relative });
        }
        await this.confirmRemoteWriteTargets("同步草稿 PLAN/config", enabledTargets.map((target) => ({
            ...target,
            expectedFiles: relativeFiles.map((file) => `${target.remotePath.replace(/\/+$/, "")}/${file}`),
            expectedFileCount: relativeFiles.length,
        })));
        await this.writeSftpManagerServerProfiles(enabledTargets.map((target) => target.id));
        const failures = [];
        for (const target of enabledTargets) {
            const result = await (async () => {
                await this.refreshProjectFileIndexesBeforeOperation?.("simpleSftpMac.uploadFiles", { localBase: root, server: this.sftpServerOptions(target), files });
                await this.invalidateProjectFileIndexes?.("文件操作开始：simpleSftpMac.uploadFiles");
                try { return await vscode.commands.executeCommand("simpleSftpMac.uploadFiles", {
                apiMode: true,
                confirm: true,
                pathConfirmed: true,
                localBase: root,
                targetId: `${target.id}-draft-run`,
                targetRole: target.role,
                server: this.sftpServerOptions(target),
                files,
                manifest: { schemaVersion: 1, kind: "simple-experiment-draft", files: relativeFiles },
            }); }
                finally {
                    await this.invalidateProjectFileIndexes?.("文件操作结束，需重新查询：simpleSftpMac.uploadFiles", relativeFiles);
                    await this.refreshProjectFileIndexesBeforeOperation?.("simpleSftpMac.uploadFiles", { localBase: root, server: this.sftpServerOptions(target), files }, "after-operation");
                }
            })();
            const item = result && typeof result === "object" ? result : {};
            if (!sftpUploadFilesSucceeded(item))
                failures.push(`${target.label}: ${stringFromRecord(item, ["error", "message"]) || "上传失败"}`);
        }
        if (failures.length)
            throw new Error(`草稿文件同步失败：${failures.join("; ")}`);
        return { targets: enabledTargets.map((target) => target.id), files: relativeFiles };
    }

