        const moveLines = archiveMoveEntries.map((entry) => `- ${safeWorkspaceChildPath(root, entry.source)}\n  -> ${safeArchiveBundleChildPath(bundleDir, entry.target)}`);
        const confirmLabel = "确认归档并同步证据";
